from __future__ import annotations

import argparse
import json
from pathlib import Path


def extract(log_path: Path, fallback_result: Path | None = None) -> dict:
    candidates = []
    if log_path.exists():
        for line in log_path.read_text(encoding="utf-8", errors="replace").splitlines():
            line = line.strip()
            if not line.startswith("{"):
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(obj, dict) and obj.get("job_id") and obj.get("branch"):
                candidates.append(obj)
    if candidates:
        return candidates[-1]

    if fallback_result and fallback_result.exists():
        obj = json.loads(fallback_result.read_text(encoding="utf-8"))
        if isinstance(obj, dict) and obj.get("job_id") and obj.get("branch"):
            return obj

    raise ValueError("Kein Agent-Ergebnis mit job_id + branch gefunden.")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--log", required=True)
    parser.add_argument("--fallback-result")
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    result = extract(
        Path(args.log),
        Path(args.fallback_result) if args.fallback_result else None,
    )
    Path(args.output).write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
